@forelse($revisions as $item)<section class="record"><h1>PENETAPAN KKM DINIYYAH</h1><h2>{{ $item->scope->subject?->name }} · Mustawa {{ $item->scope->mustawa }}</h2><p>{{ $item->scope->academicTerm?->academicYear?->name }} {{ $item->scope->academicTerm?->name }} · Versi {{ $item->version }}</p><p @class(['draft'=>!in_array($item->status,['approved','superseded'],true)])>{{ in_array($item->status,['approved','superseded'],true) ? $item->status_label : 'BELUM DISETUJUI — '.$item->status_label }}</p><p>Penyusun: {{ $item->submitter?->name ?? $item->scope->assignedTeacher?->name ?? '-' }} · Diajukan: {{ $item->submitted_at?->format('d-m-Y H:i') ?? '-' }}</p><table><thead><tr><th style="width:40%">Unsur</th><th style="width:15%">Angka</th><th style="width:45%">Kategori</th></tr></thead><tbody>@foreach($criteriaLabels as $key=>$label)<tr><td>{{ $label }}</td><td>{{ $item->criteria[$key]['score'] ?? '-' }}</td><td>{{ $item->criteria[$key]['category'] ?? '-' }}</td></tr>@endforeach</tbody></table>@foreach($criteriaLabels as $key=>$label)<h3 style="page-break-after:avoid">Alasan {{ $label }}</h3><p class="reason">{{ $item->criteria[$key]['reason'] ?? '-' }}</p>@endforeach<div class="summary">Rumus: ROUND((Kompleksitas + Daya Dukung + Intake) / 3, 0)<br>Rata-rata: {{ $item->average === null ? 'Belum lengkap' : number_format($item->average,2,',','.') }} · <strong>KKM: {{ $item->final_kkm ?? 'Belum lengkap' }}</strong></div><p>Peninjau: {{ $item->reviewer?->name ?? '-' }} · Waktu peninjauan: {{ $item->reviewed_at?->format('d-m-Y H:i') ?? '-' }}</p>@if($item->review_notes)<p class="reason">Catatan peninjau: {{ $item->review_notes }}</p>@endif<p class="muted">Dicetak {{ now()->format('d-m-Y H:i') }} WIB. Berlaku bersama untuk mapel dan mustawa yang sama pada semester ini.</p></section>@empty<h1>Rekap KKM Diniyyah</h1><p>Belum ada KKM sesuai filter dan hak akses.</p>@endforelse
